/* Standalone HomeGlo manager portal */
/* Unified account and owner-only controls */
.hg-login-role-note{display:flex;justify-content:center;gap:7px;margin:14px 0 0}.hg-login-role-note span{padding:6px 9px;border:1px solid #e2d8cc;border-radius:999px;background:#faf7f2;color:#70675e;font-size:7px;font-weight:700;letter-spacing:.05em;text-transform:uppercase}
.hg-manager-account em{font-style:normal;color:rgba(255,255,255,.52);font-size:7px;text-transform:uppercase;letter-spacing:.07em}
.hg-manager-admin-grid{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(340px,.8fr);gap:14px}
.hg-manager-staff-list{display:grid}.hg-manager-staff-list>div{display:grid;grid-template-columns:minmax(0,1fr) 105px 150px auto;align-items:center;gap:12px;padding:14px 20px;border-bottom:1px solid #f0e9df}.hg-manager-staff-list>div:last-child{border-bottom:0}.hg-manager-staff-list>div.is-blocked{background:#fbf5f4;opacity:.78}.hg-manager-staff-list span{display:grid;gap:3px}.hg-manager-staff-list strong{font-size:9px}.hg-manager-staff-list small{color:#948b80;font-size:7px}.hg-manager-staff-list b{justify-self:start;padding:6px 9px;border-radius:999px;background:#f0ede7;color:#70685f;font-size:7px}.hg-manager-staff-actions{display:flex;justify-content:flex-end;gap:6px}.hg-manager-staff-actions button,.hg-manager-inline-action button{min-height:32px;padding:0 9px;border-radius:7px;font-size:7px;font-weight:700;cursor:pointer}.hg-manager-staff-actions .is-block,.hg-manager-inline-action .is-block{border:1px solid #dfc2bd;background:#fff7f6;color:#9b4f48}.hg-manager-staff-actions .is-unblock,.hg-manager-inline-action .is-unblock{border:1px solid #bdcfb7;background:#f5fbf3;color:#55704d}.hg-manager-staff-actions .is-delete{border:0;background:#8f4e49;color:#fff}.hg-manager-staff-you{justify-self:end;padding:6px 9px;border-radius:999px;background:#eef0ea;color:#67705f;font-size:7px;font-weight:700}.hg-manager-staff-status{min-width:0}
.hg-manager-admin-form{display:grid;gap:11px;padding:20px 22px}
.hg-manager-profile-grid{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:14px;align-items:start}
.hg-manager-profile-form{display:grid;grid-template-columns:1fr 1fr;gap:14px;padding:22px}
.hg-manager-profile-form>label{display:grid;gap:6px}
.hg-manager-profile-form>label>span,.hg-manager-profile-password label>span{font-size:8px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:#93897e}
.hg-manager-profile-form input{width:100%;height:44px;border:1px solid #ddd5ca;border-radius:9px;background:#fbfaf7;padding:0 11px;font:500 10px "Manrope",sans-serif;color:#2b2622}
.hg-manager-profile-form input:focus{outline:none;border-color:#c4693b;box-shadow:0 0 0 3px rgba(196,105,59,.08)}
.hg-manager-profile-form input[disabled]{background:#f1eee9;color:#8f867b}
.hg-manager-profile-form small{font-size:7px;line-height:1.45;color:#9a9187}
.hg-manager-profile-password{grid-column:1/-1;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:4px;padding:18px;border:1px solid #e5ddd3;border-radius:12px;background:#faf8f4}
.hg-manager-profile-password>div{grid-column:1/-1}
.hg-manager-profile-password p{margin:0 0 5px;color:#8c826f;font-size:8px;font-weight:700;letter-spacing:.13em}
.hg-manager-profile-password h3{margin:0;font:600 25px/1 "Cormorant Garamond",serif}
.hg-manager-profile-password>div>span{display:block;margin-top:7px;color:#91887d;font-size:8px}
.hg-manager-profile-password label{display:grid;gap:6px}
.hg-manager-profile-form>button{grid-column:1/-1;justify-self:start;min-height:44px;padding:0 17px;border:0;border-radius:9px;background:#c4693b;color:#fff;font-size:9px;font-weight:700;cursor:pointer}
.hg-manager-profile-summary{display:grid;justify-items:center;padding:30px 22px;text-align:center}
.hg-manager-profile-avatar{display:grid;place-items:center;width:76px;height:76px;border-radius:50%;background:#2b2622;color:#fff;font:600 34px/1 "Cormorant Garamond",serif}
.hg-manager-profile-summary h2{margin:16px 0 4px;font:600 30px/1 "Cormorant Garamond",serif}
.hg-manager-profile-summary p{margin:0;color:#81796f;font-size:9px}
.hg-manager-profile-summary>span{margin-top:12px;padding:6px 9px;border-radius:999px;background:#f0e4d8;color:#99603a;font-size:7px;font-weight:700;text-transform:uppercase}
.hg-manager-profile-summary>small{margin-top:12px;color:#999084;font-size:8px}
@media(max-width:900px){.hg-manager-profile-grid{grid-template-columns:1fr}.hg-manager-profile-summary{order:-1}.hg-manager-profile-form{grid-template-columns:1fr}.hg-manager-profile-password{grid-template-columns:1fr}.hg-manager-profile-password>div,.hg-manager-profile-form>button{grid-column:auto}}.hg-manager-admin-form label{display:grid;gap:5px}.hg-manager-admin-form label>span{font-size:7px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:#93897e}.hg-manager-admin-form input,.hg-manager-admin-form select{width:100%;height:42px;border:1px solid #ddd5ca;border-radius:8px;background:#fbfaf7;padding:0 10px;font:500 10px "Manrope",sans-serif;color:#2b2622}.hg-manager-admin-form p{margin:0;color:#8f867b;font-size:8px;line-height:1.5}.hg-manager-admin-form button{height:42px;border:0;border-radius:8px;background:#c4693b;color:#fff;font-size:9px;font-weight:700;cursor:pointer}
@media(max-width:900px){.hg-manager-admin-grid{grid-template-columns:1fr}.hg-manager-staff-list>div{grid-template-columns:1fr 100px}.hg-manager-staff-list>div>small:last-child{grid-column:1/-1}}

.hg-manager-body{margin:0;background:#f5f1ea;color:#2b2622;font-family:"Manrope",sans-serif}
.hg-manager-body *{box-sizing:border-box}
.hg-manager-body a{color:inherit}
.hg-manager-login-shell{min-height:100vh;display:grid;place-items:center;padding:28px;background:radial-gradient(circle at 15% 15%,#fff9f2 0,#f5efe7 38%,#ece5dc 100%)}
.hg-manager-auth-page{font-family:"Manrope",sans-serif;background:#f5f1ea}
.hg-manager-auth-page *{box-sizing:border-box}
.hg-manager-auth-page .hg-manager-login-shell{min-height:68vh;padding:56px 20px}
.hg-manager-login-form button[disabled]{opacity:.62;cursor:wait}
.hg-manager-login-card{width:min(440px,100%);padding:34px;border:1px solid #d9cfc2;border-radius:22px;background:#fff;box-shadow:0 24px 70px rgba(43,38,34,.09)}
.hg-manager-brand,.hg-manager-sidebar-brand{display:inline-flex;align-items:center;font:600 42px/1 "Cormorant Garamond",serif;text-decoration:none;letter-spacing:-.035em}
.hg-manager-brand>span,.hg-manager-sidebar-brand>span{width:9px;height:9px;margin-left:1px;border-radius:50%;background:#c4693b}
.hg-manager-kicker,.hg-manager-page-head p,.hg-manager-panel-head p{margin:22px 0 8px;color:#8c826f;font-size:9px;font-weight:700;letter-spacing:.17em;text-transform:uppercase}
.hg-manager-login-card h1{margin:0;font:600 43px/1 "Cormorant Garamond",serif}
.hg-manager-login-copy{margin:13px 0 22px;color:#7e766d;font-size:11px;line-height:1.65}
.hg-manager-login-form{display:grid;gap:13px}
.hg-manager-login-form label{display:grid;gap:6px}
.hg-manager-login-form label span{font-size:9px;font-weight:700}
.hg-manager-login-form input{height:48px;border:1px solid #d8cec1;border-radius:10px;padding:0 12px;background:#fbf9f6;font:500 12px "Manrope",sans-serif;outline:none}
.hg-manager-login-form input:focus{border-color:#c4693b;box-shadow:0 0 0 3px rgba(196,105,59,.08)}
.hg-password-field{position:relative;display:block;width:100%}
.hg-password-field>input{width:100%;padding-right:48px!important}
.hg-password-toggle{position:absolute;right:8px;top:50%;transform:translateY(-50%);display:grid;place-items:center;width:34px!important;height:34px!important;min-height:0!important;padding:0!important;border:0!important;border-radius:8px!important;background:transparent!important;color:#786f66!important;cursor:pointer!important}
.hg-password-toggle:hover{background:#f1ebe4!important;color:#2b2622!important}
.hg-password-toggle:focus-visible{outline:2px solid #c4693b;outline-offset:1px}
.hg-password-toggle svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.hg-password-toggle .hg-eye-closed{display:none}
.hg-password-field.is-visible .hg-eye-open{display:none}
.hg-password-field.is-visible .hg-eye-closed{display:block}
.hg-manager-login-form button{height:48px;border:0;border-radius:10px;background:#2b2622;color:#fff;font-weight:700;cursor:pointer}
.hg-manager-login-links{display:flex;justify-content:center;gap:14px;margin:12px 0 0;flex-wrap:wrap}.hg-manager-login-links a{color:#8a6250;text-decoration:none;font-size:8px;font-weight:700}.hg-manager-login-links a:hover{text-decoration:underline}.hg-manager-login-foot{margin:15px 0 0;color:#999084;font-size:8px;text-align:center}
.hg-manager-alert{margin:0 0 14px;padding:11px 13px;border-radius:10px;font-size:9px;font-weight:700}
.hg-manager-alert.is-error{background:#f5e9e7;color:#8f4e49}
.hg-manager-alert.is-success{background:#eaf1e7;color:#526346}
.hg-manager-layout{min-height:100vh;display:grid;grid-template-columns:250px minmax(0,1fr)}
.hg-manager-sidebar{position:sticky;top:0;height:100vh;display:flex;flex-direction:column;padding:28px 20px;background:#27211d;color:#fff}
.hg-manager-sidebar-brand{font-size:34px;color:#fff!important}
.hg-manager-account{display:grid;gap:3px;margin:28px 0 20px;padding:14px 13px;border:1px solid rgba(255,255,255,.1);border-radius:12px;background:rgba(255,255,255,.04)}
.hg-manager-account small{font-size:8px;color:rgba(255,255,255,.55)}
.hg-manager-account strong{font-size:10px}
.hg-manager-nav{display:grid;gap:5px}
.hg-manager-nav a{display:flex;align-items:center;gap:10px;min-height:42px;padding:0 12px;border-radius:9px;color:rgba(255,255,255,.72);text-decoration:none;font-size:9px;font-weight:700}
.hg-manager-nav a span{display:grid;place-items:center;width:24px;height:24px;border-radius:7px;background:rgba(255,255,255,.07)}
.hg-manager-nav a:hover,.hg-manager-nav a.is-active{background:#fff;color:#2b2622}
.hg-manager-nav a.is-active span{background:#f0e4d8;color:#c4693b}
.hg-manager-sidebar-bottom{margin-top:auto;display:grid;gap:5px}
.hg-manager-sidebar-bottom a{padding:10px 12px;border-radius:8px;color:rgba(255,255,255,.66);text-decoration:none;font-size:9px}
.hg-manager-sidebar-bottom a:hover{background:rgba(255,255,255,.07);color:#fff}
.hg-manager-sidebar-bottom .is-logout{color:#e7b6ae}
.hg-manager-main{min-width:0;padding:38px clamp(20px,3vw,48px) 70px}
.hg-manager-mobile-head,.hg-manager-mobile-nav{display:none}
.hg-manager-page-head{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:22px}
.hg-manager-page-head p{margin-top:0}
.hg-manager-page-head h1{margin:0;font:600 clamp(40px,5vw,64px)/.95 "Cormorant Garamond",serif;letter-spacing:-.035em}
.hg-manager-page-head>div>span{display:block;margin-top:12px;color:#81796f;font-size:10px}
.hg-manager-primary{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:44px;padding:0 16px;border-radius:9px;background:#c4693b;color:#fff!important;text-decoration:none;font-size:9px;font-weight:700}
.hg-manager-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:14px}
.hg-manager-stats a{display:grid;gap:6px;min-height:135px;padding:20px;border:1px solid #ddd5ca;border-radius:15px;background:#fff;text-decoration:none;box-shadow:0 8px 24px rgba(43,38,34,.03)}
.hg-manager-stats span{font-size:8px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:#81796f}
.hg-manager-stats strong{margin-top:auto;font:600 34px/1 "Cormorant Garamond",serif}
.hg-manager-stats small{color:#999084;font-size:8px}
.hg-manager-panel,.hg-manager-order-card{border:1px solid #ddd5ca;border-radius:16px;background:#fff;box-shadow:0 8px 24px rgba(43,38,34,.03);overflow:hidden}
.hg-manager-panel-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;padding:21px 23px 16px;border-bottom:1px solid #eee7de}
.hg-manager-panel-head p{margin:0 0 7px}
.hg-manager-panel-head h2{margin:0;font:600 29px/1 "Cormorant Garamond",serif}
.hg-manager-panel-head>a{margin-top:10px;color:#c4693b;text-decoration:none;font-size:8px;font-weight:700}
.hg-manager-order-list{display:grid}
.hg-manager-order-list>a{display:grid;grid-template-columns:70px minmax(180px,1fr) minmax(130px,.8fr) 90px 20px;align-items:center;gap:12px;padding:14px 22px;border-bottom:1px solid #f0e9df;text-decoration:none}
.hg-manager-order-list>a:last-child{border-bottom:0}
.hg-manager-order-list>a:hover{background:#fbf8f4}
.hg-manager-order-id{font:600 18px "Cormorant Garamond",serif}
.hg-manager-order-list>a>span:nth-child(2){display:grid;gap:3px}
.hg-manager-order-list>a>span:nth-child(2) strong{font-size:9px}
.hg-manager-order-list small{font-size:8px;color:#978f84}
.hg-manager-order-status{justify-self:start;padding:6px 9px;border-radius:999px;background:#f5eadf;color:#99603a;font-size:8px;font-weight:700}
.hg-manager-order-list>a>strong{text-align:right;font-size:9px}
.hg-manager-order-list i{font-style:normal;color:#b1a89d}
.hg-manager-empty{display:grid;justify-items:center;padding:46px 20px;text-align:center}
.hg-manager-empty strong{font:600 24px "Cormorant Garamond",serif}
.hg-manager-empty span{margin-top:6px;color:#91887d;font-size:9px}
.hg-manager-workflow{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:14px}
.hg-manager-workflow>div{display:grid;grid-template-columns:30px 1fr;gap:9px;padding:13px 14px;border:1px solid #ddd5ca;border-radius:12px;background:#fff}
.hg-manager-workflow b{display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:#f1e4d9;color:#c4693b;font-size:9px}
.hg-manager-workflow span{display:grid;gap:3px}
.hg-manager-workflow strong{font-size:9px}
.hg-manager-workflow small{font-size:8px;line-height:1.4;color:#958d82}
.hg-manager-orders{display:grid;gap:14px}
.hg-manager-order-card>header{display:grid;grid-template-columns:1fr minmax(280px,.8fr);gap:20px;padding:21px 23px;border-bottom:1px solid #eee7de}
.hg-manager-order-card>header p{margin:0 0 5px;color:#8e8478;font-size:8px;font-weight:700;letter-spacing:.08em}
.hg-manager-order-card>header h2{margin:0;font:600 28px/1 "Cormorant Garamond",serif}
.hg-manager-order-card>header>div:first-child>span{display:block;margin-top:6px;color:#91897f;font-size:8px}
.hg-manager-address{display:grid;justify-items:end;gap:4px;text-align:right}
.hg-manager-address small{font-size:7px;font-weight:700;text-transform:uppercase;color:#958d82}
.hg-manager-address strong{max-width:460px;font-size:8px;line-height:1.5}
.hg-manager-address button{margin-top:4px;border:1px solid #d9d0c5;border-radius:7px;background:#fff;padding:7px 9px;font-size:8px;font-weight:700;cursor:pointer}
.hg-manager-fulfilment-form{display:grid;gap:14px;padding:20px 23px;border-bottom:1px solid #eee7de}
.hg-manager-fulfilment-form:last-child{border-bottom:0}
.hg-manager-money-strip{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}
.hg-manager-money-strip>div{display:grid;gap:3px;padding:12px 13px;border:1px solid #e5ddd3;border-radius:9px;background:#faf8f4}
.hg-manager-money-strip span{font-size:7px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:#93897e}
.hg-manager-money-strip strong{font-size:13px}
.hg-manager-money-strip small{font-size:7px;color:#9a9187}
.hg-manager-supplier-line{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}
.hg-manager-supplier-line>div{display:grid;gap:3px}
.hg-manager-supplier-line small{font-size:7px;text-transform:uppercase;font-weight:700;color:#93897e}
.hg-manager-supplier-line strong{font-size:10px}
.hg-manager-supplier-line span{font-size:8px;color:#91887d}
.hg-manager-supplier-line>a{display:inline-flex;align-items:center;min-height:36px;padding:0 12px;border-radius:8px;background:#2b2622;color:#fff;text-decoration:none;font-size:8px;font-weight:700}
.hg-manager-line-items{display:grid;gap:7px}
.hg-manager-line-items>div{display:grid;grid-template-columns:42px 1fr;gap:9px;align-items:center}
.hg-manager-line-items img,.hg-manager-line-items i{display:block;width:42px;height:42px;border-radius:8px;background:#eee8df;object-fit:cover}
.hg-manager-line-items span{display:grid;gap:3px}
.hg-manager-line-items strong{font-size:9px}
.hg-manager-line-items small{font-size:8px;color:#92897e}
.hg-manager-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}
.hg-manager-fields label{display:grid;gap:5px}
.hg-manager-fields label>span{font-size:7px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:#93897e}
.hg-manager-fields input,.hg-manager-fields select,.hg-manager-fields textarea{width:100%;margin:0;border:1px solid #ddd5ca;border-radius:8px;background:#fbfaf7;padding:9px 10px;font:500 10px "Manrope",sans-serif;color:#2b2622}
.hg-manager-fields input,.hg-manager-fields select{height:40px}
.hg-manager-fields textarea{resize:vertical}
.hg-manager-fields .is-wide{grid-column:1/-1}
.hg-manager-notify{display:flex;align-items:flex-start;gap:9px;padding:11px 12px;border:1px solid #e3dbd1;border-radius:9px;background:#faf8f4}
.hg-manager-notify input{margin-top:2px}
.hg-manager-notify span{display:grid;gap:2px}
.hg-manager-notify strong{font-size:8px}
.hg-manager-notify small{font-size:8px;color:#91887d}
.hg-manager-form-actions{display:flex;align-items:center;justify-content:flex-end;gap:8px;flex-wrap:wrap}
.hg-manager-form-actions button{min-height:38px;padding:0 12px;border-radius:8px;font-size:8px;font-weight:700;cursor:pointer}
.hg-manager-form-actions .is-primary{border:0;background:#c4693b;color:#fff}
.hg-manager-form-actions .is-secondary{border:1px solid #d7cec2;background:#fff;color:#2b2622}
.hg-manager-form-actions button[disabled]{opacity:.45;cursor:not-allowed}
.hg-manager-status{margin-right:auto;padding:6px 9px;border-radius:999px;background:#f0ede7;color:#736b63;font-size:8px;font-weight:700}
.hg-manager-product-list{display:grid}
.hg-manager-product-row{display:grid;grid-template-columns:48px minmax(180px,1.4fr) 110px 120px 110px 80px;align-items:center;gap:12px;padding:12px 20px;border-bottom:1px solid #f0e9df}
.hg-manager-product-row:last-child{border-bottom:0}
.hg-manager-product-row img{width:48px;height:48px;border-radius:9px;object-fit:cover;background:#eee8df}
.hg-manager-product-row>span{display:grid;gap:3px;min-width:0}
.hg-manager-product-row>span:first-of-type strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.hg-manager-product-row strong{font-size:9px}
.hg-manager-product-row small{font-size:7px;color:#948c82}
.hg-manager-product-row a{justify-self:end;color:#c4693b;text-decoration:none;font-size:8px;font-weight:700}
.hg-manager-product-row em{justify-self:end;color:#aaa096}
.hg-manager-supplier-grid{display:grid;gap:14px}
.hg-manager-supplier-products{display:grid}
.hg-manager-supplier-products>div{display:grid;grid-template-columns:42px 1fr auto;align-items:center;gap:10px;padding:11px 18px;border-bottom:1px solid #f0e9df}
.hg-manager-supplier-products>div:last-child{border-bottom:0}
.hg-manager-supplier-products img{width:42px;height:42px;border-radius:8px;object-fit:cover}
.hg-manager-supplier-products span{display:grid;gap:3px}
.hg-manager-supplier-products strong{font-size:9px}
.hg-manager-supplier-products small{font-size:8px;color:#938b80}
.hg-manager-supplier-products a{color:#c4693b;text-decoration:none;font-size:8px;font-weight:700}
@media(max-width:1100px){.hg-manager-layout{grid-template-columns:210px minmax(0,1fr)}.hg-manager-stats{grid-template-columns:repeat(2,1fr)}.hg-manager-order-list>a{grid-template-columns:60px 1fr 100px 18px}.hg-manager-order-list .hg-manager-order-status{display:none}.hg-manager-product-row{grid-template-columns:48px 1fr 100px 110px 75px}.hg-manager-product-row>span:nth-of-type(4){display:none}}
